<script nonce="{{ csrf_token() }}">function requestLineForModel(id){var q=parseInt($('#model-booking-quantity-'+id).val(),10),d=parseInt($('#model-booking-discipline-'+id).val(),10),c=parseInt($('#model-booking-company-'+id).val(),10);if(!q||!d||!c){window.alert('Enter a total needed quantity, discipline, and destination site for each model.');return null}return{model_id:id,quantity:q,discipline_id:d,company_id:c}}$(document).on('click','.add-model-to-request-cart',function(){var l=requestLineForModel(+$(this).data('model-id'));if(l)addLinesToRequestCart([l],false)});$(function(){var $t=$('#requestableModelsTable'),$category=$('#requestableModelsCategoryFilter');if(!$t.length)return;var options={filterAlgorithm:function(row,filters){var selected=filters&&filters.category;return !selected||$('<div>').html(row.category||'').text().trim()===selected}};$category.on('change',function(){var category=$(this).val();$t.bootstrapTable('filterBy',category?{category:category}:{},options)});var bootstrapTable=$t.data('bootstrap.table');var selected=bootstrapTable&&bootstrapTable.filterColumns?bootstrapTable.filterColumns.category:'';$category.val(selected||'');if(selected)$t.bootstrapTable('filterBy',{category:selected},options);$('.fixed-table-toolbar .search input').attr('placeholder','Search models or technical specifications')})</script>
